const input = $input.first().json;
const prevData = $('Build LLM Prompt').first().json;
const statusCode = input.statusCode || 200;

// Handle LLM API error
if (statusCode >= 400) {
  return {
    json: {
      success: false,
      error: {
        code: statusCode,
        message: input.body?.error?.message || 'LLM API error',
        status: 'LLM_ERROR'
      }
    }
  };
}

// Extract LLM response content
const content = input.body?.content?.[0]?.text || '';

// Parse JSON from LLM response
let parsed;
try {
  // Try to extract JSON from the response
  const jsonMatch = content.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    parsed = JSON.parse(jsonMatch[0]);
  } else {
    throw new Error('No JSON found in response');
  }
} catch (e) {
  return {
    json: {
      success: false,
      error: {
        code: 500,
        message: 'Failed to parse LLM response: ' + e.message,
        status: 'PARSE_ERROR',
        raw_response: content.substring(0, 500)
      }
    }
  };
}

// Calculate confidence based on missing fields
const extracted = parsed.extracted || parsed;
const missingFields = parsed.missing_fields || [];
const schemaFields = Object.keys(prevData.schema.fields || {});
const totalFields = schemaFields.length;
const foundFields = totalFields - missingFields.length;
const confidence = totalFields > 0 ? Math.round((foundFields / totalFields) * 100) / 100 : 1;

return {
  json: {
    success: true,
    extracted: extracted,
    confidence: confidence,
    missing_fields: missingFields,
    notes: parsed.notes || null,
    meta: {
      provider: 'anthropic',
      model: prevData.llm_model,
      document_type: prevData.context.type,
      language: prevData.context.language,
      input_length: prevData.text.length
    }
  }
};

